mapper.select:
SELECT a.ID, a.PERSONNEL_CODE, a.PERSONNEL_NAME, a.PERSONNEL_AGE, a.PHONE, b.COMMUNITY_NAME, c.AREA_NAME, d.BUILD_NAME, a.HOUSE_NUMBER, a.PERSONNEL_STATE, a.NAT_RESULT, a.INOCULATE, a.SEVEN_DAY_TRIP, a.IS_UD, a.IS_QUARANTINE, a.QUARANTINE_POLICY FROM `my_personnel` a LEFT JOIN `my_community` b ON a.COMMUNITY_CODE = b.COMMUNITY_CODE LEFT JOIN `my_community_area` c ON a.AREA_CODE = c.AREA_CODE LEFT JOIN `my_community_build` d ON a.BUILD_CODE = d.BUILD_CODE WHERE a.COMMUNITY_CODE = #{dto.communityCode} AND a.AREA_CODE = #{dto.areaCode} AND a.BUILD_CODE IN
#{item}
GROUP BY(a.ID)
